public static void popAll(MethodVisitor mv, int onStack) {
    if (onStack == 0) return;
    for (; onStack > 1; onStack -= 2) {
        mv.visitInsn(POP2);
    }
    if (onStack==1) {
        mv.visitInsn(POP);
    }
}

